	private enum Result
	{
		accept,
		noMatch,
		contextFound
	}

	private struct Context
	{
		public long bPos;

		public long rPos;

		public int cCol;

		public int lNum;

		public int state;

		public int cChr;
	}

	private struct BufferContext
	{
		internal ScanBuff buffSv;

		internal int chrSv;

		internal int cColSv;

		internal int lNumSv;
	}

	private ILoggerFactory _loggerFactory;

	private ScanBuff buffer;

	private int currentScOrd;

	private static int parserMax;

	private const int maxAccept = 89;

	private const int initial = 90;

	private const int eofNum = 0;

	private const int goStart = -1;

	private const int INITIAL = 0;

	private const int COMMENT = 1;

	public static int Pass;

	public static bool emitPass;

