	private Context ctx;

	private long readPos;

	private ILogger Logger { get; set; }

	public ScanBuff Buffer => buffer;

	private long yypos => tokPos;

	private int yyline => tokLin;

	private int yycol => tokCol;

	public string yytext
	{
		get
		{
			if (tokTxt == null)
			{
				tokTxt = buffer.GetString(tokPos, tokEPos);
			}
			return tokTxt;
		}
	}

	public long yyleng
	{
		get
		{
			if (tokELin == tokLin)
			{
				return tokECol - tokCol;
			}
			return tokEPos - tokPos;
		}
	}

	internal int YY_START
	{
		get
		{
			return currentScOrd;
		}
		set
		{
			currentScOrd = value;
			currentStart = startState[value];
		}
	}

	public Scanner(ILoggerFactory loggerFactory)
	{
		SetupLogger(loggerFactory);
	}

	public Scanner(Stream file, ILoggerFactory loggerFactory)
		: this(file)
	{
		SetupLogger(loggerFactory);
	}

	private void SetupLogger(ILoggerFactory loggerFactory)
	{
		_loggerFactory = loggerFactory ?? XbimServices.Current.GetLoggerFactory();
		Logger = _loggerFactory.CreateLogger<Scanner>();
	}

	public override void yyerror(string format, params object[] args)
	{
		string text = string.Format(format, args);
		Logger?.LogError("Illegal character found at line {0}, column {1}\n{2}", yyline, yycol, text);
	}

	private static int GetMaxParseToken()
	{
		FieldInfo field = typeof(Tokens).GetField("maxParseToken");
		if (!(field == null))
		{
			return (int)field.GetValue(null);
		}
		return int.MaxValue;
	}

	public void SetValue()
	{
		yylval.strVal = yytext;
	}

