	private int NextState()
	{
		if (code == -1)
		{
			return 0;
		}
		return nextState[state][code];
	}

	private BufferContext MkBuffCtx()
	{
		BufferContext result = default(BufferContext);
		result.buffSv = buffer;
		result.chrSv = code;
		result.cColSv = cCol;
		result.lNumSv = lNum;
		return result;
	}

	private void RestoreBuffCtx(BufferContext value)
	{
		buffer = value.buffSv;
		code = value.chrSv;
		cCol = value.cColSv;
		lNum = value.lNumSv;
	}

	public Scanner(Stream file)
	{
		SetSource(file);
	}

	public Scanner()
	{
	}

	private void GetCode()
	{
		if (code == 10)
		{
			cCol = -1;
			lNum++;
		}
		readPos = buffer.Pos;
		code = buffer.Read();
		if (code > -1)
		{
			cCol++;
		}
	}

	private void MarkToken()
	{
		buffer.Mark();
		tokPos = readPos;
		tokLin = lNum;
		tokCol = cCol;
	}

	private void MarkEnd()
	{
		tokTxt = null;
		tokEPos = readPos;
		tokELin = lNum;
		tokECol = cCol;
	}

	private int Peek()
	{
		int num = code;
		int num2 = cCol;
		int num3 = lNum;
		long pos = buffer.Pos;
		GetCode();
		int result = code;
		lNum = num3;
		cCol = num2;
		code = num;
		buffer.Pos = pos;
		return result;
	}

	public void SetSource(string source, int offset)
	{
		buffer = ScanBuff.GetBuffer(source);
		buffer.Pos = offset;
		lNum = 0;
		code = 10;
		GetCode();
	}

	public void SetSource(IList<string> source)
	{
		buffer = ScanBuff.GetBuffer(source);
		code = 10;
		lNum = 0;
		GetCode();
	}

	public void SetSource(Stream source)
	{
		buffer = ScanBuff.GetBuffer(source);
		lNum = 0;
		code = 10;
		GetCode();
	}

	public override int yylex()
	{
		int num;
		do
		{
			num = Scan();
		}
		while (num >= parserMax);
		return num;
	}

	private void yyless(long n)
	{
		buffer.Pos = tokPos;
		cCol = tokCol - 1;
		GetCode();
		lNum = tokLin;
		for (int i = 0; i < n; i++)
		{
			GetCode();
		}
		MarkEnd();
	}

	private void _yytrunc(int n)
	{
		yyless(yyleng - n);
	}

	internal void BEGIN(int next)
	{
		currentScOrd = next;
		currentStart = startState[next];
	}

	private int Scan()
	{
		try
		{
			while (true)
			{
				state = currentStart;
				int num;
				while ((num = NextState()) == -1)
				{
					GetCode();
				}
				MarkToken();
				state = num;
				GetCode();
				bool flag = false;
				while ((num = NextState()) > 0)
				{
					if (state <= 89 && num > 89)
					{
						SaveStateAndPos(ref ctx);
