	private void SaveStateAndPos(ref Context ctx)
	{
		ctx.bPos = buffer.Pos;
		ctx.rPos = readPos;
		ctx.cCol = cCol;
		ctx.lNum = lNum;
		ctx.state = state;
		ctx.cChr = code;
	}

	private void RestoreStateAndPos(ref Context ctx)
	{
		buffer.Pos = ctx.bPos;
		readPos = ctx.rPos;
		cCol = ctx.cCol;
		lNum = ctx.lNum;
		state = ctx.state;
		code = ctx.cChr;
	}

